package io.atlas.modules.market;
import io.atlas.modules.market.repository.MarketRepository;import io.atlas.modules.market.repository.MarketRepository.*;import io.atlas.modules.market.model.MarketPolicy;import io.atlas.modules.database.DatabaseConfig;import java.util.*;
public final class MarketRepositoryTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static Draft draft(UUID seller,String kind,UUID pokemon){return new Draft(UUID.randomUUID(),seller,"MarketFixture",kind,pokemon,"{\"fixture\":true}","Fixture",123);}
 public static void main(String[] args)throws Exception{
  if(!DatabaseConfig.DATABASE.equals("atlas_dev")||DatabaseConfig.PORT!=25432)throw new IllegalStateException("Isolated dev required");check(MarketPolicy.formatPrice(200000000).equals("200.000.000")&&MarketPolicy.formatPrice(1000).equals("1.000"),"Brazilian thousands separators");check(MarketPolicy.adjustPrice(1,100,false)==1&&MarketPolicy.adjustPrice(999999999,100,true)==1000000000L,"GUI price stays within bounds");check(MarketPolicy.maxHours(List.of())==24&&MarketPolicy.maxHours(List.of("VIP"))==48&&MarketPolicy.maxHours(List.of("VIPPLUS"))==96&&MarketPolicy.maxHours(List.of("VIPPLUSPLUS"))==168,"approved duration caps");var sellers=new ArrayList<UUID>();var pool=java.util.concurrent.Executors.newFixedThreadPool(12);var repo=new MarketRepository();
  try{
   check(MarketPolicy.limit(List.of())==5&&MarketPolicy.limit(List.of("VIP"))==6&&MarketPolicy.limit(List.of("VIPPLUS"))==8&&MarketPolicy.limit(List.of("VIPPLUSPLUS","VIP"))==10&&MarketPolicy.limit(List.of("adm","dono"))==5,"actual VIP limits");check(!MarketPolicy.price(0)&&!MarketPolicy.price(1000000001L)&&MarketPolicy.price(1),"price bounds");
   for(int limit:List.of(5,6,8,10)){UUID seller=UUID.randomUUID();sellers.add(seller);var jobs=new ArrayList<java.util.concurrent.Future<Boolean>>();for(int i=0;i<12;i++)jobs.add(pool.submit(()->new MarketRepository().prepare(draft(seller,"ITEM",null),limit)));int total=0;for(var j:jobs)if(j.get())total++;check(total==limit,"concurrent tier limit "+limit);check(!repo.prepare(draft(seller,"POKEMON",UUID.randomUUID()),limit),"combined item/Pokemon quota");}
   UUID seller=UUID.randomUUID(),buyer=UUID.randomUUID();sellers.add(seller);var d=draft(seller,"POKEMON",UUID.randomUUID());check(repo.prepare(d,5),"prepare");check(!repo.prepare(draft(seller,"POKEMON",d.pokemon()),5),"one live listing per Pokemon");check(repo.transition(d.id(),"PREPARING","ACTIVE"),"activate");check(!repo.buy(d.id(),seller)&&!repo.cancel(d.id(),buyer),"ownership and self purchase");var a=pool.submit(()->repo.buy(d.id(),buyer));var c=pool.submit(()->repo.cancel(d.id(),seller));check(a.get()!=c.get(),"buy/cancel CAS exactly one winner");var state=repo.find(d.id()).orElseThrow().state();check(new MarketRepository().find(d.id()).orElseThrow().price()==123,"durable payload/price");check(repo.transition(d.id(),state,"SOLD"),"final state");check(repo.withdraw(buyer,"POKEMON")==0&&repo.withdraw(seller,"POKEMON")==1&&repo.withdraw(seller,"POKEMON")==0,"one withdrawal and correct owner");check(repo.credit(d.id(),"PENDING","PAYING")&&!repo.credit(d.id(),"PENDING","PAYING")&&repo.credit(d.id(),"PAYING","PAID"),"credit CAS");
   UUID combined=UUID.randomUUID();sellers.add(combined);var one=draft(combined,"ITEM",null);var two=draft(combined,"POKEMON",UUID.randomUUID());check(repo.prepare(one,5)&&repo.prepare(two,5),"mixed drafts");repo.transition(one.id(),"PREPARING","ACTIVE");repo.transition(two.id(),"PREPARING","ACTIVE");check(repo.list("ALL",combined,0,"").size()==2&&repo.list("ITEM",combined,0,"").size()==1&&repo.list("POKEMON",combined,0,"").size()==1,"combined listing and category filters");check(repo.list("ALL",null,0,"Fixture").stream().anyMatch(l->l.id().equals(one.id()))&&repo.list("ALL",null,0,"Fixture").stream().anyMatch(l->l.id().equals(two.id())),"public mixed search");repo.transition(one.id(),"ACTIVE","SOLD");repo.transition(two.id(),"ACTIVE","SOLD");check(repo.withdraw(combined,"ALL")==2&&repo.withdraw(combined,"ALL")==0,"combined earnings withdrawal");
   UUID filters=UUID.randomUUID();sellers.add(filters);var cheap=draft(filters,"ITEM",null).price(10).duration(21600);var expensive=draft(filters,"ITEM",null).price(900);var shiny=draft(filters,"POKEMON",UUID.randomUUID()).price(500);for(var entry:List.of(cheap,expensive,shiny)){check(repo.prepare(entry,5),"filter fixture prepare");repo.transition(entry.id(),"PREPARING","ACTIVE");}repo.classify(cheap.id(),"BLOCKS",0);repo.classify(expensive.id(),"MINERALS",0);repo.classify(shiny.id(),"OTHER",8|16|2|4);
   var cheapFirst=new io.atlas.modules.market.model.MarketBrowse("ALL",true,0,"",io.atlas.modules.market.model.MarketBrowse.Sort.CHEAP,io.atlas.modules.market.model.MarketBrowse.ItemFilter.ALL,io.atlas.modules.market.model.MarketBrowse.PokemonFilter.NONE);check(repo.list(cheapFirst,filters).getFirst().id().equals(cheap.id()),"SQL cheapest sort");check(repo.list(cheapFirst.sort(true),filters).getFirst().id().equals(expensive.id()),"SQL most expensive sort");check(repo.list(cheapFirst.items(true),filters).size()==1,"block category filter");for(var f:List.of(io.atlas.modules.market.model.MarketBrowse.PokemonFilter.SHINY,io.atlas.modules.market.model.MarketBrowse.PokemonFilter.LEGENDARY,io.atlas.modules.market.model.MarketBrowse.PokemonFilter.FEMALE,io.atlas.modules.market.model.MarketBrowse.PokemonFilter.HIDDEN)){var browse=new io.atlas.modules.market.model.MarketBrowse("POKEMON",true,0,"",cheapFirst.sort(),io.atlas.modules.market.model.MarketBrowse.ItemFilter.ALL,f);check(repo.list(browse,filters).size()==1,"native metadata filter "+f);}var expires=repo.find(cheap.id()).orElseThrow().expiresAt();check(java.time.Duration.between(java.time.Instant.now(),expires).toMinutes()>=359,"selected duration starts at publication");repo.transition(cheap.id(),"ACTIVE","PAYING");repo.transition(cheap.id(),"PAYING","ACTIVE");check(repo.find(cheap.id()).orElseThrow().expiresAt().equals(expires),"retry does not extend deadline");
   try(var connection=java.sql.DriverManager.getConnection(DatabaseConfig.jdbcUrl(),DatabaseConfig.USER,DatabaseConfig.PASSWORD);var statement=connection.prepareStatement("UPDATE market_listings SET expires_at=now()-interval '1 second' WHERE id=?")){statement.setObject(1,cheap.id());statement.executeUpdate();}check(!repo.buy(cheap.id(),buyer),"expired listing cannot charge buyer");check(repo.expire()==1,"expiry queues exactly one return even with seller offline");var expired=repo.find(cheap.id()).orElseThrow();check(expired.state().equals("CANCEL_REQUESTED")&&expired.endReason().equals("EXPIRED")&&expired.payload().contains("fixture"),"expired asset payload preserved for return");check(repo.expire()==0,"expiry is idempotent");check(repo.transition(cheap.id(),"CANCEL_REQUESTED","RETURNING")&&repo.transition(cheap.id(),"RETURNING","CANCELLED"),"same durable return states");check(repo.list("ALL",filters,0,"").stream().anyMatch(l->l.id().equals(cheap.id())&&l.endReason().equals("EXPIRED")),"expiry visible in owner history");
   System.out.println("MarketRepositoryTest PASS: VIP limits, concurrent quotas, combined quotas/listings/search/earnings, unique Pokemon, ownership, buy/cancel race, durability and one withdrawal");
  }finally{pool.shutdownNow();try(var cn=java.sql.DriverManager.getConnection(DatabaseConfig.jdbcUrl(),DatabaseConfig.USER,DatabaseConfig.PASSWORD);var q=cn.prepareStatement("DELETE FROM market_listings WHERE seller=?")){for(var s:sellers){q.setObject(1,s);q.executeUpdate();}}}
 }
}